## The Corrected Implementation

Here's how I'd rebuild this, keeping it efficient but thread-safe:

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    ready     chan struct{} // Signals when loading is complete
    err       error         // Store load error for waiters
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex
    ttl    time.Duration
    loader LoadFunc
    stats  Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Try read lock first for valid cached entries
    c.mu.RLock()
    if entry, ok := c.data[key]; ok {
        if time.Now().Before(entry.ExpiresAt) && entry.ready == nil {
            c.mu.RUnlock()
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        }
        // Entry is loading - wait on the channel
        if entry.ready != nil {
            ready := entry.ready
            c.mu.RUnlock()
            select {
            case <-ready:
                return c.getLoaded(key)
            case <-ctx.Done():
                return nil, ctx.Err()
            }
        }
    }
    c.mu.RUnlock()

    // Need to load - acquire write lock
    c.mu.Lock()
    // Double-check after acquiring write lock
    if entry, ok := c.data[key]; ok {
        if time.Now().Before(entry.ExpiresAt) && entry.ready == nil {
            c.mu.Unlock()
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        }
        if entry.ready != nil {
            ready := entry.ready
            c.mu.Unlock()
            select {
            case <-ready:
                return c.getLoaded(key)
            case <-ctx.Done():
                return nil, ctx.Err()
            }
        }
    }

    // Create loading entry with signal channel
    ready := make(chan struct{})
    entry := &CacheEntry{ready: ready}
    c.data[key] = entry
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    // Load outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        delete(c.data, key)
        entry.err = err
    } else {
        c.data[key] = &CacheEntry{
            Value:     value,
            ExpiresAt: time.Now().Add(c.ttl),
        }
    }
    c.mu.Unlock()
    close(ready) // Signal all waiters

    if err != nil {
        return nil, err
    }
    return value, nil
}

func (c *Cache) getLoaded(key string) (interface{}, error) {
    c.mu.RLock()
    defer c.mu.RUnlock()
    if entry, ok := c.data[key]; ok && entry.ready == nil {
        return entry.Value, nil
    }
    return nil, nil // Entry was deleted or errored
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[key] = &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
    }
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            if value, err := c.Get(ctx, k); err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()
    now := time.Now()
    for key, entry := range c.data {
        if entry.ready == nil && now.After(entry.ExpiresAt) {
            delete(c.data, key)
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}
```

